import SwiftUI
import XCTest
@testable import CatfolioIOS

final class AccountIdentityShapeTests: XCTestCase {
    func testOutlineIsSlightlyFullerThanReferenceAtBothBadgeSizes() {
        // Left silhouette of the green avatar in the supplied 589 px screenshot,
        // normalized to its 141 px square. These are image measurements, not
        // points generated by the implementation's superellipse equation.
        let measuredEdges: [(y: CGFloat, x: CGFloat)] = [
            (0.021, 0.311), (0.057, 0.219), (0.092, 0.162),
            (0.163, 0.091), (0.234, 0.049), (0.305, 0.020),
            (0.376, 0.006)
        ]
        for size in [CGFloat(24), 72] {
            let rect = CGRect(x: 13, y: 21, width: size, height: size)
            let path = AccountIdentityShape().path(in: rect)
            XCTAssertEqual(path.boundingRect.minX, rect.minX, accuracy: 0.001)
            XCTAssertEqual(path.boundingRect.maxX, rect.maxX, accuracy: 0.001)
            XCTAssertEqual(path.boundingRect.minY, rect.minY, accuracy: 0.001)
            XCTAssertEqual(path.boundingRect.maxY, rect.maxY, accuracy: 0.001)
            XCTAssertTrue(path.contains(CGPoint(x: rect.midX, y: rect.midY)))
            XCTAssertTrue(path.contains(CGPoint(x: rect.minX + size * 0.12,
                                               y: rect.minY + size * 0.12)),
                          "Open the corners just beyond the original silhouette")
            XCTAssertFalse(path.contains(CGPoint(x: rect.minX + size * 0.105,
                                                y: rect.minY + size * 0.105)),
                           "Keep the adjustment small and the corners rounded")

            for edge in measuredEdges {
                // Check all four quarters and the reflected top/bottom edges.
                for reflectX in [false, true] {
                    for reflectY in [false, true] {
                        for transpose in [false, true] {
                            // Permit a little outward expansion from the reference,
                            // without shrinking it or straightening the whole side.
                            for inset in [CGFloat(-0.04), 0.01] {
                                var x = reflectX ? 1 - edge.x - inset : edge.x + inset
                                var y = reflectY ? 1 - edge.y : edge.y
                                if transpose { swap(&x, &y) }
                                let point = CGPoint(x: rect.minX + x * size, y: rect.minY + y * size)
                                XCTAssertEqual(path.contains(point), inset > 0,
                                               "Badge silhouette must remain close to the reference at \(point)")
                            }
                        }
                    }
                }
            }
        }
    }
}
